window.AUTH=window.AUTH||{};window.AUTH["22-846"]={"d":"22-846","id":"2023/22-846","n":"Department of Agriculture Rural Development Rural Housing Service v. Kirtz","briefs":[{"k":"petitioner","label":"Brief of petitioner Department of Agriculture Rural Development Rural Housing Service","date":"2023-08-15","url":"https://www.supremecourt.gov/DocketPDF/22/22-846/275398/20230815163427932_22-846%20USDA%20v.%20Kirtz.pdf","side":"pet","n":120},{"k":"respondent","label":"Brief of respondent Reginald Kirtz","date":"2023-09-25","url":"https://www.supremecourt.gov/DocketPDF/22/22-846/280393/20230925150024945_Final%20brief.pdf","side":"res","n":164},{"k":"reply","label":"Reply of petitioner Department of Agriculture Rural Development Rural Housing Service","date":"2023-10-25","url":"https://www.supremecourt.gov/DocketPDF/22/22-846/286107/20231025175458840_22-846%20USDA%20Rural%20Development%20Rural%20Housing%20Serv.%20v.%20Kirtz.pdf","side":"pet","n":64}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r03_4gcj.pdf","tr":true,"items":[{"t":"case","label":"Abitron Austria GmbH v. Hetronic Int’l, Inc.","cite":"2023 WL 4239255","y":2023,"court":"June 29","by":{"0":"32, 33"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"by":{"0":"20"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"by":{"0":"13, 16","1":"38"},"q":[{"src":"brief","b":0,"text":"When the Constitution was ratified, it was well established in English law that the Crown could not be sued without consent in its own courts.","cite":"527 U.S. 706, 715"},{"src":"brief","b":0,"text":"private suits for money damages would place unwarranted strain on the [government’s] ability to govern in accordance with the will of [its] citizens.","cite":"527 U.S. at 750"}]},{"t":"case","label":"Atascadero State Hospital v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"by":{"0":"10, 21, 23","2":"5"},"q":[{"src":"brief","b":0,"text":"general authorization for suit in federal court.","cite":"473 U.S. 234, 246"},{"src":"brief","b":2,"text":"‘specifically’ define[] ‘recipient’ to include states.","cite":"473 U.S. at 245"}]},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"0":"32","1":"27, 28","2":"11"},"q":[{"src":"brief","b":0,"text":"constitute a clear statement that Congress meant the statute to","cite":"572 U.S. 844, 860"},{"src":"argument","who":"Chief Justice Roberts","text":"And I'm thinking in particular of our decision in the Bond case, the -- the -- the chemical on the doorknob that is under one interpretation, perhaps literal interpretation of the statute would be covered by the Chemical Weapons Treaty."},{"src":"argument","who":"Mr. Joshi","text":"I think Bond -- Bond is a good foil for this case. The Court found -- your -- your opinion for the Court found that the statute was ambiguous."}]},{"t":"case","label":"City of Chicago v. Fulton","cite":"141 S. Ct. 585","y":2021,"id":"2020/19-357","sc":1,"by":{"0":"19"}},{"t":"case","label":"Daniel v. National Park Service","cite":"891 F.3d 762","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/762/","by":{"0":"35"}},{"t":"case","label":"Dellmuth v. Muth","cite":"491 U.S. 223","y":1989,"id":"1988/87-1855","sc":1,"by":{"0":"28","1":"35, 39, 46"},"q":[{"src":"brief","b":0,"text":"recourse to legislative history will be futile","cite":"491 U.S. 223, 230"}]},{"t":"case","label":"Doe v. Chao","cite":"540 U.S. 614","y":2004,"id":"2003/02-1377","sc":1,"by":{"0":"37, 38"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"19"}},{"t":"case","label":"Employees of the Department of Public Health & Welfare v. Department of Public Health & Welfare","cite":"411 U.S. 279","y":1973,"id":"1972/71-1021","sc":1,"by":{"0":"10, 25-28","1":"6, 7, 37, 43–47","2":"6"},"q":[{"src":"brief","b":0,"text":"clear language [indicating] that the constitutional immunity was swept away.","cite":"411 U.S. at 285"},{"src":"argument","who":"Mr. Snyder","text":"And as the Court's decision in Employees shows, the mere use of a general term defined elsewhere in the statute isn't enough to eliminate the sovereign immunity defense."},{"src":"argument","who":"Mr. Snyder","text":"I think that the statutes in both Utility Air and Employees had similar provisions that said this definition applies everywhere. In Utility Air, the Court said but we know that Congress didn't always use the defined term in a sense that carried its defined meaning, and so, when it appears in the provision at issue, it's not unambiguous that --"},{"src":"argument","who":"Mr. Snyder","text":"Our first argument is that even if you think the cause of action covers both sovereign and non-sovereign defendants, as this Court recognized in Employees, the -- the question of whether the government -- or their -- Congress has lifted the sovereign immunity defense is analytically distinct from it."}]},{"t":"case","label":"Environmental Defense v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"by":{"0":"29","2":"14"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"by":{"0":"9, 15, 20, 36","1":"12, 13, 39, 41, 42","2":"4, 12"},"q":[{"src":"brief","b":0,"text":"if there is a plausible interpretation of the statute that would not authorize money damages against the Government,","cite":"566 U.S. 284, 290-291"},{"src":"brief","b":0,"text":"[a]ny ambiguities in the statutory language are to be construed in favor of immunity, so that the Government’s consent to be sued is never enlarged beyond what a fair reading of the text requires.","cite":"566 U.S. 284, 290"},{"src":"brief","b":1,"text":"sovereign immunity is ‘clearly discernable’ from the statute itself.","cite":"566 U.S. at 291"},{"src":"brief","b":2,"text":"‘unequivocally express[ed]’ its intent to waive immunity ‘in statutory text.’","cite":"566 U.S. 284, 290"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"supply a waiver that is not clearly evident from the language of the statute.","cite":"566 U. S., at 290"}]},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"by":{"0":"9, 13, 14","1":"37, 38","2":"10, 16"},"q":[{"src":"brief","b":0,"text":"ha[s] a cause of action for damages.","cite":"510 U.S. 471, 483-484"},{"src":"brief","b":2,"text":"whether there has been a waiver of sovereign immunity.","cite":"510 U.S. 471, 484"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"to impose liability on a sovereign, a plaintiff must identify both a `source of substantive law' that `provides an avenue for relief ' and `a waiver of sovereign immunity.'","cite":"510 U. S. 471, 484"}]},{"t":"case","label":"Financial Oversight & Management Board for Puerto Rico v. Centro de Periodismo Investigativo, Inc.","cite":"143 S. Ct. 1176","y":2023,"id":"2022/22-96","sc":1,"by":{"0":"9, 14-21","1":"12, 13, 36, 37, 38","2":"1, 3, 4, 8-10"},"q":[{"src":"brief","b":0,"text":"a statute says in so many words that it is stripping immunity.","cite":"143 S. Ct. at 1184"},{"src":"brief","b":0,"text":"sa[id] in so many words that it is stripping immunity.","cite":"143 S. Ct. at 1184"},{"src":"argument","who":"Mr. Snyder","text":"And my answer is that it's not unusual for Congress to create a cause of action that applies to a range of defendants, some of whom will still have defenses from other background principles of the law. Now, in the cases that this Court was referring to in the Financial Oversight and Management Board --"},{"src":"argument","who":"Mr. Snyder","text":"And so, in Financial Oversight and Management Board, the Court said that when Congress has expressly authorized suits in that way, it would effectively negate the statutory language to allow the assertion of a sovereign immunity defense."},{"src":"argument","who":"Mr. Snyder","text":"So I read the Court's decision in Financial Oversight and Management Board to say that. I think that's the only way that you can reconcile cases like Kimel on the one hand and Employees on the other, is to say that Congress distinguishes in this way."}]},{"t":"case","label":"Fitzpatrick v. IRS","cite":"665 F.2d 327","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/665/327/","by":{"0":"38"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"0":"35","1":"31"},"q":[{"src":"brief","b":1,"text":"‘differences in language’ in the same statute generally ‘convey differences in meaning,’","cite":"582 U.S. 79, 86"}]},{"t":"case","label":"International Primate Protection League v. Administrators of Tulane Educational Fund","cite":"500 U.S. 72","y":1991,"id":"1990/90-89","sc":1,"by":{"0":"14"},"q":[{"src":"brief","b":0,"text":"defense * * * that it is not amenable to suit.","cite":"500 U.S. 72, 86"}]},{"t":"case","label":"Kimel v. Florida Board of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"by":{"0":"19, 20","1":"26, 39, 40, 47","2":"8, 9"},"q":[{"src":"brief","b":1,"text":"any agency of … a State, or a political subdivision of a State.","cite":"528 U.S. at 74"},{"src":"brief","b":1,"text":"never required that Congress make its clear statement in a single section","cite":"528 U.S. at 76"},{"src":"brief","b":2,"text":"clearly demonstrate[d] Congress’s intent to subject the States to suit for money damages,","cite":"528 U.S. at 74"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"make its clear statement in a single section or in statutory provisions enacted at the same time.","cite":"528 U. S. 62, 76"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"make its clear statement in a single section","cite":"528 U. S., at 76"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"clear statement in one statutory subsection by looking to provisions in [an]other subsection.","cite":"528 U. S., at 104"},{"src":"argument","who":"Justice Sotomayor","text":"We had the same problem in the Kimel case, and in the Kimel case, we had three layers of reference to the waiver of sovereign immunity, and we didn't require magic words."},{"src":"argument","who":"Mr. Snyder","text":"So, in Kimel, there was language in the cause of action itself that was there only for the purpose of authorizing suits --"},{"src":"argument","who":"Justice Kavanaugh","text":"So then, to pick up on Justice Kagan's questions earlier, if you see Employees on one side of the line and you see cases like Kimel on the other side of the line, where the -- where the reference to the public entities is in the cause of action itself, that's slicing it pretty thin."}]},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"143 S. Ct. 1689","y":2023,"id":"2022/22-227","sc":1,"by":{"0":"17","1":"12, 13, 14, 27, 30, 41, 42"},"q":[{"src":"argument","who":"Mr. Snyder","text":"So last term, in Lac du Flambeau, for example, there was an express waiver of sovereign immunity that made absolutely clear that what Congress was intending to do was waive sovereign immunity, and it did so on behalf of governmental units and then defined governmental units elsewhere in the statute."},{"src":"argument","who":"Mr. Joshi","text":"It's going to -- what -- what's -- what the Court's going to do, as it did in Lac du Flambeau, is to say we're going to take the words Congress has given us and we're going to interpret it."}]},{"t":"case","label":"Lane v. Pena","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"by":{"0":"6, 15, 20","1":"39"},"q":[{"src":"brief","b":0,"text":"waiver of the government’s immunity ‘must be unequivocally expressed in statutory text,’","cite":"518 U.S. 187, 192"}]},{"t":"case","label":"Middlesex County Sewerage Authority v. National Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"by":{"0":"24"}},{"t":"case","label":"Nevada Department of Human Resources v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"by":{"0":"19","1":"40","2":"8"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"0":"16"}},{"t":"case","label":"Return Mail, Inc. v. United States Postal Service","cite":"139 S. Ct. 1853","y":2019,"id":"2018/17-1594","sc":1,"by":{"0":"23, 29, 30","1":"21"},"q":[{"src":"brief","b":1,"text":"[i]n the absence of an express statutory definition,","cite":"139 S. Ct. 1853, 1861"}]},{"t":"case","label":"Robinson v. Department of Education","cite":"140 S. Ct. 1440","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/1440/","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"waiver of sovereign immunity [in FCRA] would * * * have a significant impact on the public fisc.","cite":"140 S. Ct. 1440, 1442"}]},{"t":"case","label":"Robinson v. United States Department of Education","cite":"917 F.3d 799","y":2019,"url":"https://www.courtlistener.com/c/F.3d/917/799/","by":{"0":"34","1":"28","2":"8"},"q":[{"src":"brief","b":1,"text":"subject States to both compensatory and punitive damages","cite":"917 F.3d 799, 805"}]},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"by":{"0":"11, 18, 34","1":"10, 28, 30","2":"8, 18"},"q":[{"src":"argument","who":"Mr. Snyder","text":"The -- the other two parts of the answer that I promised Justice Alito I was going to get out, we would -- we think it's significant that the 1996 amendments occurred just months after Seminole Tribe."},{"src":"argument","who":"Mr. Snyder","text":"But my understanding of Respondent's argument is that Congress was intending to eliminate sovereign immunity in 1681n and o, and if that's right, then Congress is acting blatantly unconstitutionally with respect to the states and didn't say anything at all about the Seminole Tribe decision from just a few months earlier."},{"src":"argument","who":"Mr. Joshi","text":"It's simply that what Seminole Tribe and its progeny hold is that where there's a conflict between what Congress wants and what the state wants, the state wins absent -- unless the -- it's in a few discrete areas where the Constitution abrogates state sovereign immunity or it's a Fourteenth Amendment case."}]},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"by":{"0":"13, 15, 21, 39","1":"12, 42","2":"5"},"q":[{"src":"brief","b":0,"text":"The essence of sovereign immunity * * * is that remedies against the government differ from general remedies principles applicable to private litigants.","cite":"563 U.S. 277, 291 n.8"},{"src":"brief","b":0,"text":"[t]he requirement of a clear statement in the text of [a] statute ensures that Congress has specifically considered * * * sovereign immunity and has intentionally legislated on the matter.","cite":"563 U.S. at 290"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"a clear statement in the text of the statute.","cite":"563 U. S. 277, 290"}]},{"t":"case","label":"Spector v. Norwegian Cruise Line Ltd.","cite":"545 U.S. 119","y":2005,"id":"2004/03-1388","sc":1,"by":{"0":"21","1":"42, 43"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"0":"2, 3, 19"},"q":[{"src":"brief","b":0,"text":"promote efficiency in the Nation’s banking system and to protect consumer privacy,","cite":"534 U.S. 19, 23"},{"src":"brief","b":0,"text":"‘cardinal principle of statutory construction’ that ‘a statute ought, upon the whole, to be so construed that, if it can be prevented, no clause, sentence, or word shall be superfluous, void, or insignificant.’","cite":"534 U.S. 19, 31"}]},{"t":"case","label":"United States v. California","cite":"297 U.S. 175","y":1936,"id":"scdb/1935-140","sc":1,"by":{"0":"32","1":"26"}},{"t":"case","label":"United States v. Cooper Corp.","cite":"312 U.S. 600","y":1941,"id":"scdb/1940-054","sc":1,"by":{"0":"30","2":"15"}},{"t":"case","label":"United States v. Idaho","cite":"508 U.S. 1","y":1993,"id":"1992/92-190","sc":1,"by":{"0":"15"}},{"t":"case","label":"United States v. Nordic Village, Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"by":{"0":"7","2":"13"},"q":[{"src":"brief","b":0,"text":"[a]mbiguity exists when there is a ‘plausible’ reading of the statute that does not impose ‘monetary liability on the Government.’","cite":"503 U.S. 30, 37"}]},{"t":"case","label":"United States v. Public Utilities Commission","cite":"345 U.S. 295","y":1953,"id":"scdb/1952-073","sc":1,"by":{"0":"29","1":"20, 21"},"q":[{"src":"brief","b":1,"text":"their inclusion would radically transform those programs and render them unworkable as written.","cite":"345 U.S. 295"}]},{"t":"case","label":"United States v. Shaw","cite":"309 U.S. 495","y":1940,"id":"scdb/1939-063","sc":1,"by":{"0":"16"}},{"t":"case","label":"United States v. Sherwood","cite":"312 U.S. 584","y":1941,"id":"scdb/1940-058","sc":1,"by":{"0":"13","1":"11"},"q":[{"src":"brief","b":1,"text":"The United States, as sovereign, is immune from suit save as it consents to be sued.","cite":"312 U.S. 584, 586"}]},{"t":"case","label":"United States v. Testan","cite":"424 U.S. 392","y":1976,"id":"1975/74-753","sc":1,"by":{"0":"9, 13"},"q":[{"src":"brief","b":0,"text":"long has been established * * * that the United States, as sovereign, ‘is immune from suit save as it consents to be sued.’","cite":"424 U.S. 392, 399"}]},{"t":"case","label":"United States v. Williams","cite":"514 U.S. 527","y":1995,"id":"1994/94-395","sc":1,"by":{"0":"6, 7, 20","1":"28, 39"}},{"t":"case","label":"United States Department of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"by":{"0":"15","1":"25"},"q":[{"src":"brief","b":0,"text":"a common rule, with which [courts] presume congressional familiarity, that any waiver of the National Government’s sovereign immunity must be unequivocal.","cite":"503 U.S. 607, 615"}]},{"t":"case","label":"Utility Air Regulatory Group v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"0":"10, 28, 30","1":"20","2":"14"},"q":[{"src":"brief","b":0,"text":"a statutory term— even one defined in the statute—‘may take on distinct characters from association with distinct statutory objects calling for different implementation strategies.’","cite":"573 U.S. 302, 320"},{"src":"brief","b":2,"text":"a statutory term—even one defined in the statute—‘may take on distinct characters from association with distinct statutory objects calling for different implementation strategies.’","cite":"573 U.S. 302, 320"},{"src":"argument","who":"Mr. Snyder","text":"And I'd -- I'd say our argument on that front is under the Court's decision in Utility Air. I would say that's the best decision for that part of our argument."},{"src":"argument","who":"Mr. Snyder","text":"I think the Court's decision in Utility Air is really significant on this and, in particular, the structure of the Court's reasoning in that decision."},{"src":"argument","who":"Mr. Snyder","text":"So the reason is that just as in Utility Air, there were other provisions of the Act that used \"air pollutant\" in a sense narrower than its defined meaning."}]},{"t":"case","label":"Wyatt v. Cole","cite":"504 U.S. 158","y":1992,"id":"1991/91-126","sc":1,"by":{"0":"13"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"0":"11, 34"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":"17","2":"3"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"by":{"0":"17","2":"3"},"q":[{"src":"brief","b":0,"text":"seeking relief other than money damages * * * shall not be dismissed * * * on the ground that [they are brought] against the United States.","cite":"5 U.S.C. 702"},{"src":"brief","b":2,"text":"seeking relief other than money damages * * * shall not be dismissed * * * on the ground that it is against the United States.","cite":"5 U.S.C. 702"}]},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 1681b","url":"https://www.law.cornell.edu/uscode/text/15/1681b","subs":["(b)(2)","(a)(1)","(a)(3)","(b)(3)(A)","(b)(4)(A)","(f)"],"by":{"0":"5, 25, 4","1":"17, 2, 15, 16, 16, 16, 26"}},{"t":"usc","label":"15 U.S.C. § 1681m","url":"https://www.law.cornell.edu/uscode/text/15/1681m","subs":["(a)"],"by":{"0":"5","1":"3"}},{"t":"usc","label":"15 U.S.C. § 1681s","url":"https://www.law.cornell.edu/uscode/text/15/1681s","subs":["(a)(2)","(c)","(b)(1)(H)","(a)","(a)(2)(C)","(c)(1)(B)","(c)(5)"],"by":{"0":"5, 5, 5, 5","1":"3, 9, 24, 25, 26, 4, 21, 22, 24, 24, 4, 21, 22, 24, 25, 26, 25, 24"},"q":[{"src":"brief","b":1,"text":"in the event of a knowing violation, which constitutes a pattern or practice of violations of","cite":"15 U.S.C. § 1681s(a)"},{"src":"brief","b":1,"text":"shall be enforced exclusively as provided under section 1681s … by the Federal agencies and officials and the State officials identified in section 1681s.","cite":"15 U.S.C. § 1681s"}]},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","by":{"0":"29","1":"20"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","subs":["(b)","(a)(1)"],"by":{"0":"3, 2","1":"35","2":"1"}},{"t":"usc","label":"15 U.S.C. § 1681a","url":"https://www.law.cornell.edu/uscode/text/15/1681a","subs":["(b)(1970)","(a)","(b)","(f)","(o)(2)(B)"],"by":{"0":"3, 18, 25, 25","1":"3, 14, 1, 3, 5, 8, 12, 14, 2, 15"},"q":[{"src":"brief","b":0,"text":"government or governmental subdivision or agency,","cite":"15 U.S.C. 1681a(b)"},{"src":"brief","b":1,"text":"any … government or governmental subdivision or agency.","cite":"15 U.S.C. § 1681a(b)"}]},{"t":"usc","label":"15 U.S.C. § 1681n","url":"https://www.law.cornell.edu/uscode/text/15/1681n","subs":["(1970)","(a)(1)(A)","(a)(1)(B)","(a)","(a)(1)"],"stext":{"head":"§1681n. Civil liability for willful noncompliance","paras":[[0,"(a) In general"],[0,"Any person who willfully fails to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1)(A) any actual damages sustained by the consumer as a result of the failure or damages of not less than $100 and not more than $1,000; or"],[1,"(B) in the case of liability of a natural person for obtaining a consumer report under false pretenses or knowingly without a permissible purpose, actual damages sustained by the consumer as a result of the failure or $1,000, whichever is greater;"],[1,"(2) such amount of punitive damages as the court may allow; and"],[1,"(3) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Civil liability for knowing noncompliance"],[0,"Any person who obtains a consumer report from a consumer reporting agency under false pretenses or knowingly without a permissible purpose shall be liable to the consumer reporting agency for actual damages sustained by the consumer reporting agency or $1,000, whichever is greater."],[0,"(c) Attorney's fees"],[0,"Upon a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."],[0,"(d) Clarification of willful noncompliance"],[0,"For the purposes of this section, any person who printed an expiration date on any receipt provided to a consumer cardholder at a point of sale or transaction between December 4, 2004, and June 3, 2008, but otherwise complied with the requirements of section 1681c(g) of this title for such receipt shall not be in willful noncompliance with section 1681c(g) of this title by reason of printing such expiration date on the receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681n?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 5, 5","1":"1, 4, 9, 12, 14, 15","2":"2, 4, 10, 13, 14, 16-20, 22, 17, 21"},"q":[{"src":"argument","who":"Mr. Joshi","text":"Thus, where Section 1681n generally provides for damages against \"any person,\" 1681n(a)(1)(B) creates a special remedy for certain violations by a natural person."}]},{"t":"usc","label":"15 U.S.C. § 1681o","url":"https://www.law.cornell.edu/uscode/text/15/1681o","subs":["(1970)","(a)"],"by":{"0":"2, 5","1":"1, 4, 9, 12, 14","2":"2, 4, 10, 13, 14, 16-20, 22, 17, 21"}},{"t":"usc","label":"15 U.S.C. § 1681q","url":"https://www.law.cornell.edu/uscode/text/15/1681q","subs":["(1970)"],"stext":{"head":"§1681q. Obtaining information under false pretenses","paras":[[0,"Any person who knowingly and willfully obtains information on a consumer from a consumer reporting agency under false pretenses shall be fined under title 18, imprisoned for not more than 2 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681q?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 5","1":"3, 9, 21–24","2":"14-17, 19"},"q":[{"src":"brief","b":0,"text":"person who knowingly and willfully obtains information on a consumer from a consumer reporting agency under false pretenses.","cite":"15 U.S.C. 1681q"},{"src":"brief","b":1,"text":"[a]ny person who knowingly and willfully obtains information on a consumer from a consumer reporting agency under false pretenses shall be fined under title 18, imprisoned for not more than 2 years, or both.","cite":"15 U.S.C. § 1681q"},{"src":"brief","b":2,"text":"apply[] the FCRA’s definition of ‘person’ to","cite":"15 U.S.C. 1681q"}]},{"t":"usc","label":"15 U.S.C. § 1681r","url":"https://www.law.cornell.edu/uscode/text/15/1681r","subs":["(1970)"],"by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 1681d","url":"https://www.law.cornell.edu/uscode/text/15/1681d","subs":["(a)"],"by":{"0":"3, 4","1":"3"}},{"t":"usc","label":"15 U.S.C. § 1681k","url":"https://www.law.cornell.edu/uscode/text/15/1681k","subs":["(a)(1)","(b)"],"by":{"0":"25, 4, 29, 29","1":"16"}},{"t":"usc","label":"15 U.S.C. § 1681s-2","url":"https://www.law.cornell.edu/uscode/text/15/1681s-2","subs":["(b)","(b)(1)","(a)","(a)(1)","(c)","(d)"],"by":{"0":"36, 37, 4, 6","1":"3, 5, 19, 25, 26, 4, 24, 25, 24, 1, 4, 4, 4, 25"},"q":[{"src":"brief","b":1,"text":"shall be enforced exclusively as provided under section 1681s … by the Federal agencies and officials and the State officials identified in section 1681s.","cite":"15 U.S.C. § 1681s-2(d)"}]},{"t":"usc","label":"15 U.S.C. § 1681u","url":"https://www.law.cornell.edu/uscode/text/15/1681u","subs":["(a)","(g)","(j)","(l)","(m)"],"stext":{"head":"§1681u. Disclosures to FBI for counterintelligence purposes","paras":[[0,"(a) Identity of financial institutions"],[0,"Notwithstanding section 1681b of this title or any other provision of this subchapter, a consumer reporting agency shall furnish to the Federal Bureau of Investigation the names and addresses of all financial institutions (as that term is defined in section 3401 of title 12) at which a consumer maintains or has maintained an account, to the extent that information is in the files of the agency, when presented with a written request for that information that includes a term that specifically identifies a consumer or account to be used as the basis for the production of that information, signed by the Director of the Federal Bureau of Investigation, or the Director's designee in a position not lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge of a Bureau field office designated by the Director, which certifies compliance with this section. The Director or the Director's designee may make such a certification only if the Director or the Director's designee has determined in writing, that such information is sought for the conduct of an authorized investigation to protect against international terrorism or clandestine intelligence activities, provided that such an investigation of a United States person is not conducted solely upon the basis of activities protected by the first amendment to the Constitution of the United States."],[0,"(b) Identifying information"],[0,"Notwithstanding the provisions of section 1681b of this title or any other provision of this subchapter, a consumer reporting agency shall furnish identifying information respecting a consumer, limited to name, address, former addresses, places of employment, or former places of employment, to the Federal Bureau of Investigation when presented with a written request that includes a term that specifically identifies a consumer or account to be used as the basis for the production of that information, signed by the Director or the Director's designee in a position not lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge of a Bureau field office designated by the Director, which certifies compliance with this subsection. The Director or the Director's designee may make such a certification only if the Director or the Director's designee has determined in writing that such information is sought for the conduct of an authorized investigation to protect against international terrorism or clandestine intelligence activities, provided that such an investigation of a United States person is not conducted solely upon the basis of activities protected by the first amendment to the Constitution of the United States."],[0,"(c) Court order for disclosure of consumer reports"],[0,"Notwithstanding section 1681b of this title or any other provision of this subchapter, if requested in writing by the Director of the Federal Bureau of Investigation, or a designee of the Director in a position not lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge in a Bureau field office designated by the Director, a court may issue an order ex parte, which shall include a term that specifically identifies a consumer or account to be used as the basis for the production of the information, directing a consumer reporting agency to furnish a consumer report to the Federal Bureau of Investigation, upon a showing in camera that the consumer report is sought for the conduct of an authorized investigation to protect against international terrorism or clandestine intelligence activities, provided that such an investigation of a United States person is not conducted solely upon the basis of activities protected by the first amendment to the Constitution of the United States. The terms of an order issued under this subsection shall not disclose that the order is issued for purposes of a counterintelligence investigation."],[0,"(d) Prohibition of certain disclosure"],[0,"(1) Prohibition"],[0,"(A) In general"],[2,"If a certification is issued under subparagraph (B) and notice of the right to judicial review under subsection (e) is provided, no consumer reporting agency that receives a request under subsection (a) or (b) or an order under subsection (c), or officer, employee, or agent thereof, shall disclose or specify in any consumer report, that the Federal Bureau of Investigation has sought or obtained access to information or records under subsection (a), (b), or (c)."],[0,"(B) Certification"],[2,"The requirements of subparagraph (A) shall apply if the Director of the Federal Bureau of Investigation, or a designee of the Director whose rank shall be no lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge of a Bureau field office, certifies that the absence of a prohibition of disclosure under this subsection may result in—"],[3,"(i) a danger to the national security of the United States;"],[3,"(ii) interference with a criminal, counterterrorism, or counterintelligence investigation;"],[3,"(iii) interference with diplomatic relations; or"],[3,"(iv) danger to the life or physical safety of any person."],[0,"(2) Exception"],[0,"(A) In general"],[2,"A consumer reporting agency that receives a request under subsection (a) or (b) or an order under subsection (c), or officer, employee, or agent thereof, may disclose information otherwise subject to any applicable nondisclosure requirement to—"],[3,"(i) those persons to whom disclosure is necessary in order to comply with the request;"],[3,"(ii) an attorney in order to obtain legal advice or assistance regarding the request; or"],[3,"(iii) other persons as permitted by the Director of the Federal Bureau of Investigation or the designee of the Director."],[0,"(B) Application"],[2,"A person to whom disclosure is made under subparagraph (A) shall be subject to the nondisclosure requirements applicable to a person to whom a request under subsection (a) or (b) or an order under subsection (c) is issued in the same manner as the person to whom the request is issued."],[0,"(C) Notice"],[2,"Any recipient that discloses to a person described in subparagraph (A) information otherwise subject to a nondisclosure requirement shall inform the person of the applicable nondisclosure requirement."],[0,"(D) Identification of disclosure recipients"],[2,"At the request of the Director of the Federal Bureau of Investigation or the designee of the Director, any person making or intending to make a disclosure under clause (i) or (iii) of subparagraph (A) shall identify to the Director or such designee the person to whom such disclosure will be made or to whom such disclosure was made prior to the request."],[0,"(e) Judicial review"],[0,"(1) In general"],[1,"A request under subsection (a) or (b) or an order under subsection (c) or a non-disclosure requirement imposed in connection with such request under subsection (d) shall be subject to judicial review under section 3511 of title 18."],[0,"(2) Notice"],[1,"A request under subsection (a) or (b) or an order under subsection (c) shall include notice of the availability of judicial review described in paragraph (1)."],[0,"(f) Payment of fees"],[0,"The Federal Bureau of Investigation shall, subject to the availability of appropriations, pay to the consumer reporting agency assembling or providing report or information in accordance with procedures established under this section a fee for reimbursement for such costs as are reasonably necessary and which have been directly incurred in searching, reproducing, or transporting books, papers, records, or other data required or requested to be produced under this section."],[0,"(g) Limit on dissemination"],[0,"The Federal Bureau of Investigation may not disseminate information obtained pursuant to this section outside of the Federal Bureau of Investigation, except to other Federal agencies as may be necessary for the approval or conduct of a foreign counterintelligence investigation, or, where the information concerns a person subject to the Uniform Code of Military Justice, to appropriate investigative authorities within the military department concerned as may be necessary for the conduct of a joint foreign counterintelligence investigation."],[0,"(h) Rules of construction"],[0,"Nothing in this section shall be construed to prohibit information from being furnished by the Federal Bureau of Investigation pursuant to a subpoena or court order, in connection with a judicial or administrative proceeding to enforce the provisions of this subchapter. Nothing in this section shall be construed to authorize or permit the withholding of information from the Congress."],[0,"(i) Reports to Congress"],[0,"(1) On a semiannual basis, the Attorney General shall fully inform the Permanent Select Committee on Intelligence and the Committee on Banking, Finance and Urban Affairs of the House of Representatives, and the Select Committee on Intelligence and the Committee on Banking, Housing, and Urban Affairs of the Senate concerning all requests made pursuant to subsections (a), (b), and (c)."],[0,"(2) In the case of the semiannual reports required to be submitted under paragraph (1) to the Permanent Select Committee on Intelligence of the House of Representatives and the Select Committee on Intelligence of the Senate, the submittal dates for such reports shall be as provided in section 3106 of title 50."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681u?type=usc&year=mostrecent&link-type=html"},"by":{"0":"25, 33","1":"7, 10, 11, 30, 31, 32, 17, 16, 29, 31, 29, 7, 10, 30, 31, 31, 31","2":"19, 20"},"q":[{"src":"brief","b":0,"text":"[a]ny agency or department of the United States.","cite":"15 U.S.C. 1681u"},{"src":"brief","b":1,"text":"second, more specific waiver of sovereign immunity within FCRA itself,","cite":"15 U.S.C. § 1681u(j)"}]},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"25"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)(1970)","(b)(2000)","(b)"],"stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"by":{"0":"25, 19","1":"39, 40","2":"6, 8, 9"},"q":[{"src":"brief","b":0,"text":"against any employer (including a public agency) in any Federal or State court of competent jurisdiction.","cite":"29 U.S.C. 216(b)"},{"src":"brief","b":2,"text":"against any employer (including a public agency).","cite":"29 U.S.C. 216(b)"}]},{"t":"usc","label":"5 U.S.C. § 6381","url":"https://www.law.cornell.edu/uscode/text/5/6381","by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","by":{"0":"5"}},{"t":"usc","label":"25 U.S.C. § 2710","url":"https://www.law.cornell.edu/uscode/text/25/2710","subs":["(d)(7)(A)(i)"],"by":{"0":"18"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"0":"33"}},{"t":"usc","label":"15 U.S.C. § 1122","url":"https://www.law.cornell.edu/uscode/text/15/1122","subs":["(a)"],"by":{"0":"17","2":"3"}},{"t":"usc","label":"33 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/33/1401","by":{"0":"23"}},{"t":"usc","label":"33 U.S.C. § 1402","url":"https://www.law.cornell.edu/uscode/text/33/1402","subs":["(e)"],"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"any private person or entity, or any officer, employee, agent, department, agency, or instrumentality of the Federal Government, of any State or local unit of government, or of any foreign government,","cite":"33 U.S.C. 1402(e)"}]},{"t":"usc","label":"33 U.S.C. § 1415","url":"https://www.law.cornell.edu/uscode/text/33/1415","subs":["(g)(i)"],"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"may commence a civil suit * * * to enjoin any person, including the United States and any other governmental instrumentality or agency (to the extent permitted by the eleventh amendment to the Constitution), who is alleged to be in violation of","cite":"33 U.S.C. 1415(g)(i)"}]},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(a)(1)","(b)","(c)(4)","(d)","(g)","(g)(1)(A)","(g)(2)(A)","(g)(4)(A)","(g)(1)(C)","(g)(1)(D)","(g)(4)"],"stext":{"head":"§552a. Records maintained on individuals","paras":[[0,"(a) Definitions.—For purposes of this section—"],[1,"(1) the term \"agency\" means agency as defined in section 552(e) 1 of this title;"],[1,"(2) the term \"individual\" means a citizen of the United States or an alien lawfully admitted for permanent residence;"],[1,"(3) the term \"maintain\" includes maintain, collect, use, or disseminate;"],[1,"(4) the term \"record\" means any item, collection, or grouping of information about an individual that is maintained by an agency, including, but not limited to, his education, financial transactions, medical history, and criminal or employment history and that contains his name, or the identifying number, symbol, or other identifying particular assigned to the individual, such as a finger or voice print or a photograph;"],[1,"(5) the term \"system of records\" means a group of any records under the control of any agency from which information is retrieved by the name of the individual or by some identifying number, symbol, or other identifying particular assigned to the individual;"],[1,"(6) the term \"statistical record\" means a record in a system of records maintained for statistical research or reporting purposes only and not used in whole or in part in making any determination about an identifiable individual, except as provided by section 8 of title 13;"],[1,"(7) the term \"routine use\" means, with respect to the disclosure of a record, the use of such record for a purpose which is compatible with the purpose for which it was collected;"],[1,"(8) the term \"matching program\"—"],[2,"(A) means any computerized comparison of—"],[3,"(i) two or more automated systems of records or a system of records with non-Federal records for the purpose of—"],[4,"(I) establishing or verifying the eligibility of, or continuing compliance with statutory and regulatory requirements by, applicants for, recipients or beneficiaries of, participants in, or providers of services with respect to, cash or in-kind assistance or payments under Federal benefit programs, or"],[4,"(II) recouping payments or delinquent debts under such Federal benefit programs, or"],[3,"(ii) two or more automated Federal personnel or payroll systems of records or a system of Federal personnel or payroll records with non-Federal records,"],[2,"(B) but does not include—"],[3,"(i) matches performed to produce aggregate statistical data without any personal identifiers;"],[3,"(ii) matches performed to support any research or statistical project, the specific data of which may not be used to make decisions concerning the rights, benefits, or privileges of specific individuals;"],[3,"(iii) matches performed, by an agency (or component thereof) which performs as its principal function any activity pertaining to the enforcement of criminal laws, subsequent to the initiation of a specific criminal or civil law enforcement investigation of a named person or persons for the purpose of gathering evidence against such person or persons;"],[3,"(iv) matches of tax information (I) pursuant to section 6103(d) of the Internal Revenue Code of 1986, (II) for purposes of tax administration as defined in section 6103(b)(4) of such Code, (III) for the purpose of intercepting a tax refund due an individual under authority granted by section 404(e), 464, or 1137 of the Social Security Act; or (IV) for the purpose of intercepting a tax refund due an individual under any other tax refund intercept program authorized by statute which has been determined by the Director of the Office of Management and Budget to contain verification, notice, and hearing requirements that are substantially similar to the procedures in section 1137 of the Social Security Act;"],[3,"(v) matches—"],[4,"(I) using records predominantly relating to Federal personnel, that are performed for routine administrative purposes (subject to guidance provided by the Director of the Office of Management and Budget pursuant to subsection (v)); or"],[4,"(II) conducted by an agency using only records from systems of records maintained by that agency;"],[0,"if the purpose of the match is not to take any adverse financial, personnel, disciplinary, or other adverse action against Federal personnel;"],[3,"(vi) matches performed for foreign counterintelligence purposes or to produce background checks for security clearances of Federal personnel or Federal contractor personnel;"],[3,"(vii) matches performed incident to a levy described in section 6103(k)(8) of the Internal Revenue Code of 1986;"],[3,"(viii) matches performed pursuant to section 202(x)(3) or 1611(e)(1) of the Social Security Act (42 U.S.C. 402(x)(3), 1382(e)(1));"],[3,"(ix) matches performed by the Secretary of Health and Human Services or the Inspector General of the Department of Health and Human Services with respect to potential fraud, waste, and abuse, including matches of a system of records with non-Federal records; or"],[3,"(x) matches performed pursuant to section 3(d)(4) of the Achieving a Better Life Experience Act of 2014; 1"],[1,"(9) the term \"recipient agency\" means any agency, or contractor thereof, receiving records contained in a system of records from a source agency for use in a matching program;"],[1,"(10) the term \"non-Federal agency\" means any State or local government, or agency thereof, which receives records contained in a system of records from a source agency for use in a matching program;"],[1,"(11) the term \"source agency\" means any agency which discloses records contained in a system of records to be used in a matching program, or any State or local government, or agency thereof, which discloses records to be used in a matching program;"],[1,"(12) the term \"Federal benefit program\" means any program administered or funded by the Federal Government, or by any agent or State on behalf of the Federal Government, providing cash or in-kind assistance in the form of payments, grants, loans, or loan guarantees to individuals; and"],[1,"(13) the term \"Federal personnel\" means officers and employees of the Government of the United States, members of the uniformed services (including members of the Reserve Components), individuals entitled to receive immediate or deferred retirement benefits under any retirement program of the Government of the United States (including survivor benefits)."],[0,"(b) Conditions of Disclosure.—No agency shall disclose any record which is contained in a system of records by any means of communication to any person, or to another agency, except pursuant to a written request by, or with the prior written consent of, the individual to whom the record pertains, unless disclosure of the record would be—"],[1,"(1) to those officers and employees of the agency which maintains the record who have a need for the record in the performance of their duties;"],[1,"(2) required under section 552 of this title;"],[1,"(3) for a routine use as defined in subsection (a)(7) of this section and described under subsection (e)(4)(D) of this section;"],[1,"(4) to the Bureau of the Census for purposes of planning or carrying out a census or survey or related activity pursuant to the provisions of title 13;"],[1,"(5) to a recipient who has provided the agency with advance adequate written assurance that the record will be used solely as a statistical research or reporting record, and the record is to be transferred in a form that is not individually identifiable;"],[1,"(6) to the National Archives and Records Administration as a record which has sufficient historical or other value to warrant its continued preservation by the United States Government, or for evaluation by the Archivist of the United States or the designee of the Archivist to determine whether the record has such value;"],[1,"(7) to another agency or to an instrumentality of any governmental jurisdiction within or under the control of the United States for a civil or criminal law enforcement activity if the activity is authorized by law, and if the head of the agency or instrumentality has made a written request to the agency which maintains the record specifying the particular portion desired and the law enforcement activity for which the record is sought;"],[1,"(8) to a person pursuant to a showing of compelling circumstances affecting the health or safety of an individual if upon such disclosure notification is transmitted to the last known address of such individual;"],[1,"(9) to either House of Congress, or, to the extent of matter within its jurisdiction, any committee or subcommittee thereof, any joint committee of Congress or subcommittee of any such joint committee;"],[1,"(10) to the Comptroller General, or any of his authorized representatives, in the course of the performance of the duties of the Government Accountability Office;"],[1,"(11) to the Director of the Congressional Budget Office, or any authorized representative of the Director, in the course of performance of the duties of the Congressional Budget Office;"],[1,"(12) pursuant to the order of a court of competent jurisdiction; or"],[1,"(13) to a consumer reporting agency in accordance with section 3711(e) of title 31."],[0,"(c) Accounting of Certain Disclosures.—Each agency, with respect to each system of records under its control, shall—"],[1,"(1) except for disclosures made under subsections (b)(1) or (b)(2) of this section, keep an accurate accounting of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"11, 36, 36, 36, 36, 20, 36, 37, 37, 37","1":"8, 31, 33, 33, 33, 33, 33, 34, 33, 34, 33, 33, 32","2":"3, 21, 21"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","by":{"0":"23"}},{"t":"usc","label":"42 U.S.C. § 6903","url":"https://www.law.cornell.edu/uscode/text/42/6903","subs":["(15)"],"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"each department, agency, and instrumentality of the United States,","cite":"42 U.S.C. 6903(15)"}]},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","subs":["(a)(1)(B)"],"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"against any person, including the United States and any other governmental instrumentality or agency, to the extent permitted by the eleventh amendment to the Constitution.","cite":"42 U.S.C. 6972(a)(1)(B)"}]},{"t":"usc","label":"7 U.S.C. § 6943","url":"https://www.law.cornell.edu/uscode/text/7/6943","by":{"0":"5"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)"],"by":{"0":"17"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"[n]otwithstanding an assertion of sovereign immunity, sovereign immunity is abrogated as to a governmental unit . . . with respect to","cite":"11 U. S. C. § 106(a)"}]},{"t":"usc","label":"17 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/17/511","subs":["(a)"],"by":{"0":"17"}},{"t":"usc","label":"20 U.S.C. § 1080a","url":"https://www.law.cornell.edu/uscode/text/20/1080a","by":{"0":"36"}},{"t":"usc","label":"20 U.S.C. § 1087a","url":"https://www.law.cornell.edu/uscode/text/20/1087a","subs":["(b)(2)"],"by":{"0":"36"}},{"t":"usc","label":"20 U.S.C. § 1087e","url":"https://www.law.cornell.edu/uscode/text/20/1087e","subs":["(a)(1)"],"by":{"0":"36"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)"],"by":{"0":"7, 20"},"q":[{"src":"brief","b":0,"text":"deduced from broad language in the definition section","cite":"28 U.S.C. 1346(a), 2674"}]},{"t":"usc","label":"28 U.S.C. § 2674","url":"https://www.law.cornell.edu/uscode/text/28/2674","by":{"0":"7"}},{"t":"usc","label":"29 U.S.C. § 794a","url":"https://www.law.cornell.edu/uscode/text/29/794a","subs":["(a)(2)(1982)","(a)(2)","(2)(1982)"],"by":{"0":"21, 21, 20","2":"5"},"q":[{"src":"brief","b":0,"text":"recipient of federal aid under the statute.","cite":"29 U.S.C. 794a(2)"}]},{"t":"usc","label":"29 U.S.C. § 2611","url":"https://www.law.cornell.edu/uscode/text/29/2611","subs":["(4)(A)(iii)"],"by":{"0":"22"}},{"t":"usc","label":"29 U.S.C. § 2617","url":"https://www.law.cornell.edu/uscode/text/29/2617","subs":["(a)(2)"],"by":{"0":"19, 22","2":"8"},"q":[{"src":"brief","b":0,"text":"any employer (including a public agency).","cite":"29 U.S.C. 2617(a)(2)"}]},{"t":"usc","label":"31 U.S.C. § 3711","url":"https://www.law.cornell.edu/uscode/text/31/3711","subs":["(e)","(h)(2)"],"by":{"0":"36","1":"16","2":"20"}},{"t":"usc","label":"35 U.S.C. § 296","url":"https://www.law.cornell.edu/uscode/text/35/296","subs":["(a)"],"by":{"0":"17"}},{"t":"usc","label":"39 U.S.C. § 409","url":"https://www.law.cornell.edu/uscode/text/39/409","subs":["(d)(1)(A)","(d)(1)(B)"],"by":{"0":"14, 14","2":"3"},"q":[{"src":"brief","b":0,"text":"shall not be immune under any other doctrine of sovereign immunity from suit in Federal court by any person for any violation of any of those provisions of law by any officer or employee of the Postal Service,","cite":"39 U.S.C. 409(d)(1)(B)"}]},{"t":"usc","label":"43 U.S.C. § 390uu","url":"https://www.law.cornell.edu/uscode/text/43/390uu","by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"[c]onsent is given to join the United States as a necessary party defendant.","cite":"43 U.S.C. 390uu"}]},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(b)"],"by":{"0":"6"}},{"t":"case","label":"Abitron Austria GmbH v. Hetronic International, Inc.","cite":"600 U.S. 412","y":2023,"id":"2022/21-1043","sc":1,"by":{"1":"27, 28","2":"11"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"invitation to have one last drink.","cite":"532 U.S. 275, 287"}]},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"by":{"1":"13, 22"}},{"t":"case","label":"Blatchford v. Native Village of Noatak","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"certainly would grant a district court jurisdiction to hear the claim.","cite":"501 U.S. 775, 786–87 n.4"}]},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"by":{"1":"14, 19, 20"},"q":[{"src":"brief","b":1,"text":"[s]tatutory definitions control the meaning of statutory words in the usual case.","cite":"553 U.S. 124, 129"}]},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"by":{"1":"13, 41"},"q":[{"src":"brief","b":1,"text":"apply the statute according to its terms.","cite":"555 U.S. 379, 387"},{"src":"brief","b":1,"text":"must apply the statute according to its terms.","cite":"555 U.S. at 387"}]},{"t":"case","label":"Chambers v. U.S. Department of Interior","cite":"568 F.3d 998","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/568/998/","by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"an adverse agency determination resulting from inaccurate agency records.","cite":"568 F.3d 998, 1007"}]},{"t":"case","label":"Coleman v. Court of Appeals of Md.","cite":"566 U.S. 30","y":2012,"id":"2011/10-1016","sc":1,"by":{"1":"40","2":"8, 9"}},{"t":"case","label":"College Savings Bank v. Florida Prepaid Postsecondary Educational Expense Board","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"by":{"1":"43, 45, 46","2":"2, 4, 6, 7, 11"},"q":[{"src":"brief","b":2,"text":"by such overwhelming implications from the text as will leave no room for any other reasonable construction.","cite":"527 U.S. 666, 678"},{"src":"brief","b":2,"text":"did not * * * express[] with clarity Congress’s intention to supersede the [sovereign’s] immunity from suits brought by individuals.","cite":"527 U.S. at 677"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"a railroad owned and operated by PAlaabagmea . P. . runodeor fthPe Feednerdal iEnmgployPerus' bLilaibciliatytAioct.n","cite":"527 U. S., at 676"},{"src":"argument","who":"Mr. Snyder","text":"Just briefly on that, I mean, in College Savings Bank, the opinion for the Court by Justice Scalia said -- points out that Employees was written by one of the Parden dissenters over the solitary dissent of Parden's author and that it began the Court's retreat from Parden."},{"src":"argument","who":"Mr. Snyder","text":"No, we accept that you can establish it by implication. As the Court said in College Savings Bank, it has to be \"overwhelming implication.\""},{"src":"argument","who":"Justice Kavanaugh","text":"And then, in College Savings Bank, the Court makes a big point that Employees started the retreat from Parden, which was a much looser standard for waiver of sovereign immunity."}]},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"1":"32"}},{"t":"case","label":"Cook County v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"by":{"1":"23"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"by":{"1":"14, 15, 19, 35"},"q":[{"src":"brief","b":1,"text":"When a statute includes an explicit definition, [the courts] must follow that definition.","cite":"138 S. Ct. at 776"},{"src":"brief","b":1,"text":"destroy[ ] one of the statute’s major purposes.","cite":"138 S. Ct. at 778"}]},{"t":"case","label":"Eastern Transportation Co. v. United States","cite":"272 U.S. 675","y":1927,"id":"scdb/1926-107","sc":1,"by":{"1":"24"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"by":{"1":"46"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"by":{"1":"35"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"not at liberty to pick and choose among congressional enactments and must instead strive to give effect to both.","cite":"138 S. Ct. 1612, 1624"}]},{"t":"case","label":"Food Marketing Institute v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"to salvage the result, if not the reasoning, of","cite":"139 S. Ct. 2356, 2365"},{"src":"brief","b":1,"text":"a relic from a bygone era of statutory construction.","cite":"139 S. Ct. at 2364"}]},{"t":"case","label":"Fourth Estate Public Benefit Corp. v. WallStreet.com, LLC","cite":"139 S. Ct. 881","y":2019,"id":"2018/17-571","sc":1,"by":{"1":"26"}},{"t":"case","label":"Fox v. Standard Oil Co. of New Jersey","cite":"294 U.S. 87","y":1935,"id":"scdb/1934-085","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"if [courts] were free in despite of it to choose a meaning for [themselves].","cite":"294 U.S. 87, 96"}]},{"t":"case","label":"Hamer v. Neighborhood Housing Services of Chicago","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"by":{"1":"42"},"q":[{"src":"brief","b":1,"text":"resist[s] speculating whether Congress acted inadvertently.","cite":"583 U.S. 17, 25"}]},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich, L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"by":{"1":"17"}},{"t":"case","label":"Lawson v. Suwannee Fruit & Steamship Co.","cite":"336 U.S. 198","y":1949,"id":"scdb/1948-038","sc":1,"by":{"1":"14"}},{"t":"case","label":"Lebron v. National Railroad Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"1":"37, 38"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"by":{"1":"42"}},{"t":"case","label":"Markham v. Cabell","cite":"326 U.S. 404","y":1945,"id":"scdb/1945-001","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"the normal assumption is that where Congress amends only one section of a law, leaving another untouched, the two were designed to function as parts of an integrated whole.","cite":"326 U.S. 404, 411"}]},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"presume[s] that Congress is aware of existing law when it passes legislation.","cite":"571 U.S. 161, 169"}]},{"t":"case","label":"Moore v. U.S. Department of Agriculture","cite":"55 F.3d 991","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/55/991/","by":{"1":"18"}},{"t":"case","label":"Mowrer v. U.S. Department of Transportation","cite":"14 F.4th 723","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/14/723/","by":{"1":"22"},"q":[{"src":"argument","who":"Mr. Joshi","text":"Circuit in the Mowrer decision, what Judge Krause said below, which is that any contextual reason you might have for disregarding an otherwise controlling statutory definition in the criminal context is unique to the criminal context."}]},{"t":"case","label":"Newport v. Fact Concerts, Inc.","cite":"453 U.S. 247","y":1981,"id":"1980/80-396","sc":1,"by":{"1":"21"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"the text of a law controls over purported legislative intentions unmoored from any statutory text.","cite":"142 S. Ct. 2486, 2496"}]},{"t":"case","label":"Parden v. Terminal Railway Co. of Alaska Docks Department","cite":"377 U.S. 184","y":1964,"id":"1963/157","sc":1,"by":{"1":"43, 46","2":"7, 13"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"to `every' common carrier by railroad in interstate commerce,","cite":"377 U. S., at 187"},{"src":"argument","who":"Mr. Snyder","text":"I mean, I think this idea that Employees and Parden are sort of of a piece in the bad old days, I just don't think that's a plausible description of those cases."},{"src":"argument","who":"Mr. Snyder","text":"Just briefly on that, I mean, in College Savings Bank, the opinion for the Court by Justice Scalia said -- points out that Employees was written by one of the Parden dissenters over the solitary dissent of Parden's author and that it began the Court's retreat from Parden."},{"src":"argument","who":"Mr. Snyder","text":"Again, as I said, we think that this Court has reaffirmed Employees and -- and recognized that Employees began the retreat from Parden, but even just looking at the text of Employees, I think it's consistent with the argument and the distinctions that I'm drawing today."}]},{"t":"case","label":"Pennhurst State School and Hospital v. Halderman","cite":"465 U.S. 89","y":1984,"id":"1982/81-2101","sc":1,"by":{"1":"46","2":"13"}},{"t":"case","label":"Pennsylvania v. Union Gas Co.","cite":"491 U.S. 1","y":1989,"id":"1988/87-1241","sc":1,"by":{"1":"30, 43, 46, 47","2":"7"},"q":[{"src":"brief","b":1,"text":"to give fair and reasonable meaning to the text of the United States Code, adopted by various Congresses at various times.","cite":"491 U.S. at 29"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"each statute must be evaluated on its own terms.","cite":"491 U. S. 1, 13, n. 4"}]},{"t":"case","label":"Phillips v. Grendahl","cite":"312 F.3d 357","y":2002,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/312/357/","by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"Courts avoided this loophole by reasoning that since section 1681q created criminal liability for requesting ‘information on a consumer’ using false pretenses, this prohibition was a ‘requirement’ of the Act, and therefore provided the substantive basis for civil liability.","cite":"312 F.3d 357, 363–64"}]},{"t":"case","label":"Richlin Security Service Co. v. Chertoff","cite":"553 U.S. 571","y":2008,"id":"2007/06-1717","sc":1,"by":{"1":"13"},"q":[{"src":"brief","b":1,"text":"there is no ambiguity left for [it] to construe.","cite":"553 U.S. 571, 590"}]},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"by":{"1":"21","2":"16, 17"},"q":[{"src":"brief","b":2,"text":"[a] statutory term ‘may have a plain meaning in the context of a particular section’ even if it does not have ‘the same meaning in all other sections and in all other contexts.’","cite":"519 U.S. at 343"},{"src":"brief","b":2,"text":"‘each section must be analyzed to determine whether the context’ resolves ‘the issue in dispute,’","cite":"519 U.S. at 343"}]},{"t":"case","label":"Rowland v. California Men’s Colony, Unit II Men’s Advisory Council","cite":"506 U.S. 194","y":1993,"id":"1992/91-1188","sc":1,"by":{"1":"20"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"it pre- sumably would have done so expressly as it did","cite":"464 U.S. 16, 23"}]},{"t":"case","label":"Safeco Insurance Co. of America v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"by":{"1":"2, 24"},"q":[{"src":"brief","b":1,"text":"Congress enacted FCRA in 1970 to ensure fair and accurate credit reporting, promote efficiency in the banking system, and protect consumer privacy.","cite":"551 U.S. 47, 52"}]},{"t":"case","label":"SAS Institute, Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"it knew exactly how to do so—it could have simply borrowed from the statute[s] next door.","cite":"138 S. Ct. 1348, 1355"}]},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"by":{"1":"13"},"q":[{"src":"brief","b":1,"text":"if the statutory language is unambiguous and the statutory scheme is coherent and consistent,","cite":"569 U.S. 369, 380"}]},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"FCRA seeks to ensure ‘fair and accurate credit reporting.’","cite":"578 U.S. 330, 334"}]},{"t":"case","label":"Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"by":{"1":"20"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"I want to understand that because this Court, as Justice Kagan has alluded to, has said that it's virtually conclusive -- I think Sturgeon a few years ago we said that -- virtually conclusive that the definition applies."}]},{"t":"case","label":"Tanzin v. Tanvir","cite":"141 S. Ct. 486","y":2020,"id":"2020/19-71","sc":1,"by":{"1":"20, 21"},"q":[{"src":"brief","b":1,"text":"varies from a term’s ordinary meaning,","cite":"141 S. Ct. at 490"}]},{"t":"case","label":"Torres v. Texas Department of Public Safety","cite":"142 S. Ct. 2455","y":2022,"id":"2021/20-603","sc":1,"by":{"1":"29"}},{"t":"case","label":"Türkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"by":{"1":"23"},"q":[{"src":"argument","who":"Mr. Joshi","text":"Last year, in Halk Bank, you -- I think you said that criminal law can apply to foreign states and their arms. I don't -- I don't think you've said that in the context of domestic agencies."}]},{"t":"case","label":"U.S. Postal Service v. Flamingo Industries (USA) Ltd.","cite":"540 U.S. 736","y":2004,"id":"2003/02-1290","sc":1,"by":{"1":"37"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"by":{"1":"14"},"q":[{"src":"brief","b":1,"text":"Read naturally, the word ‘any’ has an expansive meaning, that is, ‘one or some indiscriminately of whatever kind.’","cite":"520 U.S. 1, 5"}]},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"by":{"1":"20"}},{"t":"case","label":"Welch v. Texas Department of Highways and Public Transportation","cite":"483 U.S. 468","y":1987,"id":"1986/85-1716","sc":1,"by":{"1":"43, 46"}},{"t":"usc","label":"15 U.S.C. § 1601-1693r","url":"https://www.law.cornell.edu/uscode/text/15/1601-1693r","by":{"1":"6, 17"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"45"}},{"t":"law","label":"Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"33"}},{"t":"usc","label":"15 U.S.C. § 1691a","url":"https://www.law.cornell.edu/uscode/text/15/1691a","subs":["(e)","(f)"],"by":{"1":"6, 17, 17","2":"12, 12"}},{"t":"usc","label":"15 U.S.C. § 1691c","url":"https://www.law.cornell.edu/uscode/text/15/1691c","subs":["(a)(9)","(c)"],"by":{"1":"25, 25"}},{"t":"usc","label":"15 U.S.C. § 1691e","url":"https://www.law.cornell.edu/uscode/text/15/1691e","subs":["(a)","(b)"],"by":{"1":"17, 6, 17","2":"12, 12"}},{"t":"law","label":"Fair Credit Reporting Act, Pub. L. No. 91-508","url":"https://www.govinfo.gov/link/statute/84/1127","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 1681c-1","url":"https://www.law.cornell.edu/uscode/text/15/1681c-1","subs":["(i)(4)"],"by":{"1":"16"}},{"t":"usc","label":"15 U.S.C. § 1681f","url":"https://www.law.cornell.edu/uscode/text/15/1681f","by":{"1":"2, 16"}},{"t":"usc","label":"15 U.S.C. § 1681g","url":"https://www.law.cornell.edu/uscode/text/15/1681g","subs":["(a)(3)(C)","(g)(1)","(g)(1)(G)"],"by":{"1":"16, 15, 15"},"q":[{"src":"brief","b":1,"text":"[a]ny person who makes or arranges loans and who uses a consumer credit score,","cite":"15 U.S.C. § 1681g(g)(1)"}]},{"t":"usc","label":"15 U.S.C. § 1681i","url":"https://www.law.cornell.edu/uscode/text/15/1681i","subs":["(a)(1)","(a)(1)(A)","(a)(2)(A)"],"by":{"1":"2, 5, 5"}},{"t":"usc","label":"15 U.S.C. § 1681p","url":"https://www.law.cornell.edu/uscode/text/15/1681p","by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"any other court of competent jurisdiction,","cite":"15 U.S.C. § 1681p"}]},{"t":"usc","label":"15 U.S.C. § 1681v","url":"https://www.law.cornell.edu/uscode/text/15/1681v","subs":["(a)"],"by":{"1":"16"}},{"t":"usc","label":"29 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/29/203","subs":["(x)","(d)"],"by":{"1":"40","2":"9"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","subs":["(a)","(k)","(o)"],"by":{"1":"40, 40, 40"}},{"t":"usc","label":"29 U.S.C. § 213","url":"https://www.law.cornell.edu/uscode/text/29/213","subs":["(b)(20)"],"by":{"1":"40"}},{"t":"law","label":"Pub. L. No. 93-579","url":"https://www.govinfo.gov/link/statute/88/1896","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/15/1602","subs":["(d)","(e)","(g)"],"by":{"1":"6, 18, 6, 18, 6, 18","2":"12, 12, 12"},"q":[{"src":"brief","b":1,"text":"Like the FCRA, the TILA and ECOA define ‘person’ to include any ‘government or governmental subdivision or agency,’ and each includes ‘person’ in its definition of the term ‘creditor.’","cite":"15 U.S.C. §§ 1602(d)"},{"src":"brief","b":1,"text":"government or governmental subdivision or agency.","cite":"15 U.S.C. §§ 1602(d)"}]},{"t":"usc","label":"15 U.S.C. § 1611","url":"https://www.law.cornell.edu/uscode/text/15/1611","by":{"1":"23"}},{"t":"usc","label":"15 U.S.C. § 1612","url":"https://www.law.cornell.edu/uscode/text/15/1612","subs":["(b)"],"by":{"1":"6, 18, 23","2":"12"}},{"t":"usc","label":"15 U.S.C. § 1640","url":"https://www.law.cornell.edu/uscode/text/15/1640","subs":["(a)"],"by":{"1":"18","2":"12"}},{"t":"usc","label":"15 U.S.C. § 78u-6","url":"https://www.law.cornell.edu/uscode/text/15/78u-6","subs":["(a)(6)"],"by":{"1":"15"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","by":{"1":"28"}},{"t":"usc","label":"15 U.S.C. § 2688","url":"https://www.law.cornell.edu/uscode/text/15/2688","by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 229F","url":"https://www.law.cornell.edu/uscode/text/18/229F","subs":["(1)(A)"],"by":{"1":"27"}},{"t":"usc","label":"28 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/28/1362","by":{"1":"29"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)","(c)"],"by":{"1":"39, 39"}},{"t":"usc","label":"42 U.S.C. § 6992e","url":"https://www.law.cornell.edu/uscode/text/42/6992e","subs":["(a)","(b)"],"by":{"1":"22","2":"15, 15"},"q":[{"src":"brief","b":2,"text":"expressly waives any immunity otherwise applicable to the United States.","cite":"42 U.S.C. 6992e(a)"}]},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(20)(D)"],"by":{"1":"47","2":"8"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"2":"18"}},{"t":"case","label":"Fitzgerald v. Barnstable School Committee","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"by":{"2":"21"}},{"t":"case","label":"Hammer v. Equifax Information Services., L.L.C.","cite":"974 F.3d 564","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/974/564/","by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"furnish [consumer reporting agencies] with consumer information only on a volun- tary basis.","cite":"974 F.3d 564, 568"}]},{"t":"case","label":"Quern v. Jordan","cite":"440 U.S. 332","y":1979,"id":"1978/77-841","sc":1,"by":{"2":"22"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"2":"21"}},{"t":"usc","label":"15 U.S.C. § 1691","url":"https://www.law.cornell.edu/uscode/text/15/1691","by":{"2":"12"}},{"t":"law","label":"Pub. L. No. 104-93","url":"https://www.govinfo.gov/link/plaw/104/public/93","by":{"2":"19, 20"}},{"t":"usc","label":"15 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/15/1601","by":{"2":"12"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"21"}}]};